() => {
  function setInput(selector, val) {
    const el = document.querySelector(selector);
    if (!el) return false;
    el.focus();
    const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(el, val);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.blur();
    return true;
  }

  setInput('#_systemfield_name', 'Pratham Modi');
  setInput('#_systemfield_email', 'prathammodi001@gmail.com');
  setInput('#2953e314-ca27-4d2b-8c40-a8197a325a49', 'Bengaluru, Karnataka, India');
  setInput('#e49092dd-c589-4165-8cb1-4f348dd7b940', '+919033393729');
  setInput('#74a9bab8-ba3a-42e8-ab40-876aff50a3ed', 'https://www.linkedin.com/in/prathammodii001/');
  setInput('#def8cf92-0f00-44d7-9987-57821eb9676c', 'https://github.com/PrathamModi001');
  setInput('#32178e06-7bfc-41d2-a9d0-96fb5bf6551a', 'https://prathammodi.dev');

  // Radio button for Visa sponsorship (No)
  const radioNo = document.querySelector('input[id*="labeled-radio-1"]');
  if (radioNo) {
    radioNo.checked = true;
    radioNo.dispatchEvent(new Event('change', { bubbles: true }));
    radioNo.click();
  }

  // File upload
  const fileInput = document.querySelector('#_systemfield_resume');
  if (fileInput) {
    const b64Data = "";
    const byteCharacters = atob(b64Data);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'application/pdf' });
    const file = new File([blob], 'Pratham_Modi_Resume.pdf', { type: 'application/pdf' });

    const dt = new DataTransfer();
    dt.items.add(file);
    fileInput.files = dt.files;
    fileInput.dispatchEvent(new Event('change', { bubbles: true }));
    fileInput.dispatchEvent(new Event('input', { bubbles: true }));
  }

  return {
    name: document.querySelector('#_systemfield_name') ? document.querySelector('#_systemfield_name').value : null,
    email: document.querySelector('#_systemfield_email') ? document.querySelector('#_systemfield_email').value : null,
    loc: document.querySelector('#2953e314-ca27-4d2b-8c40-a8197a325a49') ? document.querySelector('#2953e314-ca27-4d2b-8c40-a8197a325a49').value : null,
    radioChecked: radioNo ? radioNo.checked : null,
    fileAttached: fileInput && fileInput.files.length > 0 ? fileInput.files[0].name : null
  };
}
